S=np.load('trajS.npy'); c=np.load('trajc.npy'); a=np.load('traja.npy'); xi=np.load('trajxi.npy'); N=len(c)
def isbad(a,c): return (a[:,0]>1.9)&(a[:,0]<3.2)&(np.abs(a[:,1]-(0.07+3.3*c))<0.45)&(c<0.62)
bad=isbad(a,c)
p=np.array([-0.2676142,1.3459178,0.26077898])
def target(xi,c,w,W,x0min):
    z=xi[:,1]-(p[0]+p[1]*c+p[2]*xi[:,0])
    D=np.where(z>=0, w*np.clip(1-z/W,0,None), -w*np.clip(1+z/W,0,None))
    return D*(xi[:,0]>x0min)*(c<0.62)
def run(xi,c,D):
    xt=torch.tensor(xi); ct=torch.tensor(c); t=torch.ones(len(c))
    with torch.no_grad(): v,_=net.velocity(xt,t,ct,(),count=False)
    x1=xt-v/20; x1[:,1]+=torch.tensor(D,dtype=torch.float32)
    return np.asarray(model.decode(net,x1,ct,start_step=1))
def atyp(an,cs):
    d=[]
    for i in range(len(cs)):
        m=np.abs(c-cs[i])<0.03
        d.append(np.min(np.linalg.norm(a[m]-an[i],axis=1)))
    return np.array(d)
for w,W,x0min in [(0.65,1.0,0.0),(0.6,0.9,0.1),(0.75,1.1,0.1),(0.55,0.8,0.1)]:
    D=target(xi,c,w,W,x0min).astype(np.float32)
    an=run(xi,c,D); nb=isbad(an,c)
    mv=np.linalg.norm(an-a,axis=1)>0.3
    sel=np.where(mv)[0][:500]; dd=atyp(an[sel],c[sel])
